using System;
using System.Collections.Generic;
using System.IO;
using System.Text;
class Program {
 static byte[] data; static int[] offsets=new int[1024], lengths=new int[1024], slots=new int[2048]; static int wordCount;
 static uint WordHash(int s,int e){uint h=2166136261;for(int i=s;i<e;i++)h=(h^data[i])*16777619;return h^(h>>16);}
 static void GrowWords(){var old=slots;slots=new int[old.Length*2];foreach(int id in old)if(id!=0){int p=(int)(WordHash(offsets[id],offsets[id]+lengths[id])&(uint)(slots.Length-1));while(slots[p]!=0)p=(p+1)&(slots.Length-1);slots[p]=id;}}
 static int Intern(int s,int e){if((long)(wordCount+1)*10>=slots.Length*7L)GrowWords();int p=(int)(WordHash(s,e)&(uint)(slots.Length-1));while(slots[p]!=0){int id=slots[p];if(lengths[id]==e-s){int j=0;while(j<e-s&&data[offsets[id]+j]==data[s+j])j++;if(j==e-s)return id;}p=(p+1)&(slots.Length-1);}int next=++wordCount;if(next==offsets.Length){Array.Resize(ref offsets,next*2);Array.Resize(ref lengths,next*2);}offsets[next]=s;lengths[next]=e-s;slots[p]=next;return next;}
 sealed class Table {public ulong[] keys=new ulong[1024], counts=new ulong[1024];public int used;static ulong Hash(ulong x){x^=x>>30;x*=0xbf58476d1ce4e5b9UL;x^=x>>27;x*=0x94d049bb133111ebUL;return x^(x>>31);}void Grow(){var old=keys;var oc=counts;keys=new ulong[old.Length*2];counts=new ulong[keys.Length];for(int i=0;i<old.Length;i++)if(old[i]!=0){int p=(int)(Hash(old[i])&(uint)(keys.Length-1));while(keys[p]!=0)p=(p+1)&(keys.Length-1);keys[p]=old[i];counts[p]=oc[i];}}public void Add(ulong k){if((long)(used+1)*10>=keys.Length*7L)Grow();int p=(int)(Hash(k)&(uint)(keys.Length-1));while(keys[p]!=0&&keys[p]!=k)p=(p+1)&(keys.Length-1);if(keys[p]==0){keys[p]=k;used++;}counts[p]++;}}
 readonly record struct Row(ulong Key,ulong Count);
 static int CmpWord(int a,int b){int n=Math.Min(lengths[a],lengths[b]);for(int i=0;i<n;i++){int c=data[offsets[a]+i]-data[offsets[b]+i];if(c!=0)return c;}return lengths[a].CompareTo(lengths[b]);}
 static int Compare(Row a,Row b){int c=b.Count.CompareTo(a.Count);if(c!=0)return c;c=CmpWord((int)(a.Key>>32),(int)(b.Key>>32));return c!=0?c:CmpWord((int)(uint)a.Key,(int)(uint)b.Key);}
 static void Main(string[] args){data=File.ReadAllBytes(args[0]);for(int i=0;i<data.Length;i++)if(data[i]>='A'&&data[i]<='Z')data[i]+=32;var t=new Table();ulong total=0,pairs=0;uint prev=0;for(int i=0;i<data.Length;){byte c=data[i];if(c>='a'&&c<='z'){int start=i++;while(i<data.Length&&data[i]>='a'&&data[i]<='z')i++;uint id=(uint)Intern(start,i);total++;if(prev!=0){t.Add(((ulong)prev<<32)|id);pairs++;}prev=id;}else{if(c=='.'||c=='!'||c=='?')prev=0;i++;}}
 var top=new List<Row>(21);var comparer=Comparer<Row>.Create(Compare);for(int i=0;i<t.keys.Length;i++)if(t.keys[i]!=0&&(top.Count<20||t.counts[i]>=top[top.Count-1].Count)){var r=new Row(t.keys[i],t.counts[i]);int p=top.BinarySearch(r,comparer);if(p<0)p=~p;if(p<20){top.Insert(p,r);if(top.Count>20)top.RemoveAt(20);}}var output=new StringBuilder();output.Append("words ").Append(total).Append("\npairs ").Append(pairs).Append("\ndistinct ").Append(t.used).Append('\n');foreach(var r in top){int a=(int)(r.Key>>32),b=(int)(uint)r.Key;output.Append(r.Count).Append(' ').Append(Encoding.ASCII.GetString(data,offsets[a],lengths[a])).Append(' ').Append(Encoding.ASCII.GetString(data,offsets[b],lengths[b])).Append('\n');}Console.Write(output.ToString());}
}
